mapper.select:
SELECT DISTINCT ON (candidate.model_code) candidate.model_code,
       COALESCE(confirmation.model_type, candidate.model_type) AS model_type,
       COALESCE(array_to_string(confirmation.capabilities, ','), array_to_string(candidate.capabilities, ',')) AS capabilities,
       CASE WHEN confirmation.discovery_id IS NOT NULL THEN 'CONFIRMED_BY_ADMIN' ELSE candidate.classification END AS classification,
       candidate.display_name
FROM model_runtime.platform_provider_model_discovery discovery
JOIN model_runtime.platform_discovered_model candidate ON candidate.discovery_id = discovery.id
LEFT JOIN model_runtime.platform_model_candidate_confirmation confirmation
  ON confirmation.discovery_id = candidate.discovery_id AND confirmation.model_code = candidate.model_code
WHERE discovery.platform_provider_connection_id = #{connectionId}
  AND discovery.platform_provider_connection_revision = #{revision}
  AND discovery.succeeded = TRUE AND discovery.expires_at > #{now}
  AND candidate.model_code = #{modelCode}
  AND COALESCE(confirmation.model_type, candidate.model_type) = #{modelType}
  AND (candidate.classification <> 'REQUIRES_ADMIN_CONFIRMATION' OR confirmation.discovery_id IS NOT NULL)
ORDER BY candidate.model_code ASC, discovery.discovered_at DESC, discovery.id DESC

mapper.insert:
INSERT INTO model_runtime.platform_model_candidate_confirmation
    (discovery_id, model_code, model_type, capabilities, confirmed_by_subject_id, confirmed_at)
SELECT candidate.discovery_id, candidate.model_code, #{modelType}, ARRAY[#{capability}]::VARCHAR[], #{subjectId}, #{confirmedAt}
FROM model_runtime.platform_discovered_model candidate
WHERE candidate.discovery_id = (
    SELECT discovery.id FROM model_runtime.platform_provider_model_discovery discovery
    WHERE discovery.platform_provider_connection_id = #{connectionId}
      AND discovery.platform_provider_connection_revision = #{revision}
      AND discovery.succeeded = TRUE AND discovery.expires_at > #{now}
    ORDER BY discovery.discovered_at DESC, discovery.id DESC LIMIT 1
)
  AND candidate.model_code = #{modelCode} AND candidate.classification = 'REQUIRES_ADMIN_CONFIRMATION'
  AND NOT EXISTS (
      SELECT 1 FROM model_runtime.platform_model_candidate_confirmation confirmation
      WHERE confirmation.discovery_id = candidate.discovery_id AND confirmation.model_code = candidate.model_code
  )
